import "server-only";

import pitchesJson from "@/data/pitches.json";
import { supabase, supabaseConfigured } from "@/lib/supabase";
import type { Pitch } from "@/lib/types";

const FALLBACK_PITCHES = pitchesJson as unknown as Pitch[];

/**
 * Loads the full pitch dataset for the site.
 *
 * Prefers live Supabase (once NEXT_PUBLIC_SUPABASE_URL / _ANON_KEY are set
 * in the deployment's env vars and `supabase/schema.sql` + `seed.sql` have
 * been run against the project). Falls back to the bundled JSON snapshot
 * (generated by scripts/build_data.py from data/pitch_data.csv) otherwise,
 * so the site works out of the box before Supabase is wired up, and stays
 * up if Supabase is ever unreachable.
 */
export async function getPitches(): Promise<{
  pitches: Pitch[];
  source: "supabase" | "static";
}> {
  if (supabaseConfigured && supabase) {
    // Embed the pitchers/batters rows via their FKs (PostgREST resource
    // embedding) so the client gets the same flat shape as the bundled
    // JSON fallback (pitcher_name, batter_side, ...) without a bespoke view.
    const { data, error } = await supabase
      .from("pitches")
      .select("*, pitchers(name, throws), batters(name, side)")
      .order("pitch_no", { ascending: true });

    if (!error && data) {
      return {
        pitches: data.map(flattenSupabaseRow),
        source: "supabase",
      };
    }

    console.error("[data] Supabase query failed, using static fallback:", error?.message);
  }

  return { pitches: FALLBACK_PITCHES, source: "static" };
}

// Shape returned by the `pitches` table when embedding its `pitchers` and
// `batters` foreign-key relations via PostgREST resource embedding.
interface SupabasePitchRow extends Omit<Pitch, "pitcher_name" | "pitcher_throws" | "batter_name" | "batter_side"> {
  pitchers: { name: string; throws: string } | null;
  batters: { name: string; side: string } | null;
}

function flattenSupabaseRow(row: SupabasePitchRow): Pitch {
  const { pitchers, batters, ...rest } = row;
  return {
    ...rest,
    pitcher_name: pitchers?.name ?? "Unknown",
    pitcher_throws: pitchers?.throws ?? "Undefined",
    batter_name: batters?.name ?? "Unknown",
    batter_side: batters?.side ?? "Undefined",
  };
}
